INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38511, 'Genesis 47:12', 'Genesis', 47, 12, 'یوسف خپل پلار، خپلو ورونو او د خپل پلار ټولې کورنۍ ته د هغوی د اولادونو د شمېر سره سم خواړه برابرول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_12.mp3', '', 1761754199, 1761754199),
(38512, 'Genesis 47:13', 'Genesis', 47, 13, 'قحطي دومره سخته شوه چې په ټوله سیمه کې ډوډۍ نه وه او د کنعان او مصر خلک د لوږې له لاسه کمزوري شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_13.mp3', '', 1761754199, 1761754199),
(38513, 'Genesis 47:14', 'Genesis', 47, 14, 'د مصر او کنعان د خلکو سره چې څومره پیسې وې هغه ټولې یې د غلو د اخیستلو په بدل کې یوسف ته ورکړې او یوسف هغه پیسې واخیستلې او د فرعون په خزانه کې یې کېښودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_14.mp3', '', 1761754199, 1761754199),
(38514, 'Genesis 47:15', 'Genesis', 47, 15, 'کله چې د مصر او د کنعان د خلکو پیسې خلاصې شوې، نو ټول مصریان یوسف ته راغلل او ویې ویل: «زمونږ ټولې پیسې خلاصې شوې، مونږ ته غلې دانې راکړئ. دې ته مو مه پرېږدئ چې تاسو راته ګورئ او مونږ مړه کېږو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_15.mp3', '', 1761754199, 1761754199),
(38515, 'Genesis 47:16', 'Genesis', 47, 16, 'یوسف ځواب ورکړ: «که چېرې ستاسو پیسې خلاصې شوې وي، نو خپل حیوانات راولئ. زه به ستاسو د حیواناتو په بدل کې په تاسو باندې غلې دانې خرڅې کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_16.mp3', '', 1761754199, 1761754199),
(38516, 'Genesis 47:17', 'Genesis', 47, 17, 'نو هغوی یوسف ته خپل حیوانات راوستل او یوسف د هغوی د اسونو، پسونو، وزو، غویانو او خرو په بدل کې ورته غله ورکړه او په هغه کال یې هغوی ته د دوی د ټولو حیواناتو په بدل کې غله ورسوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_17.mp3', '', 1761754199, 1761754199),
(38517, 'Genesis 47:18', 'Genesis', 47, 18, 'کله چې هغه کال تېر شو، د قحطۍ په بل کال هغوی یوسف ته راغلل او ویې ویل: «باداره، ستاسو څخه دا حقیقت نه شو پټولی چې زمونږ ټولې پیسې خلاصې شوې دي او زمونږ حیوانات هم ستاسو شول. زمونږ سره د خپل ځان او ځمکې څخه پرته نور څه نه دي پاتې چې تاسو ته یې درکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_18.mp3', '', 1761754199, 1761754199),
(38518, 'Genesis 47:19', 'Genesis', 47, 19, 'مونږ دې ته مه پرېږدئ چې مړه شو! مه پرېږدئ چې زمونږ ځمکه شاړه شي. مونږ او زمونږ ځمکه د غلو دانو په بدل کې واخلئ. مونږ به د فرعون غلامان شو او هغه به زمونږ د ځمکې خاوند شي. مونږ ته غله راکړئ چې ژوندي پاتې شو او تخم راکړئ چې خپلې ځمکې وکرو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_19.mp3', '', 1761754199, 1761754199),
(38519, 'Genesis 47:20', 'Genesis', 47, 20, 'نو یوسف د مصر ټوله ځمکه فرعون ته واخیستله. مصریانو هر یو خپله ځمکه خرڅه کړه، ځکه چې سخته قحطي شوه او ټوله ځمکه د فرعون شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_20.mp3', '', 1761754199, 1761754199),
(38520, 'Genesis 47:21', 'Genesis', 47, 21, 'یوسف د مصر د یو سر څخه تر بل سر پورې خلک غلامان کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_21.mp3', '', 1761754199, 1761754199),
(38521, 'Genesis 47:22', 'Genesis', 47, 22, 'یوازېنۍ ځمکه چې یوسف په بیه نه وه اخیستې، هغه د کاهنانو ځمکه وه، ځکه چې کاهنانو ته به د فرعون له خوا یو څه ورکول کېدل چې خپل ژوند ورباندې وکړي. په دې سبب هغوی خپله ځمکه خرڅه نه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_22.mp3', '', 1761754199, 1761754199),
(38522, 'Genesis 47:23', 'Genesis', 47, 23, 'یوسف خلکو ته وویل: «اوس چې ما ستاسو ځمکې او تاسو د فرعون دپاره اخیستي یئ، دا دی تخم ستاسو دپاره چې په خپلو ځمکو کې یې وکرئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_23.mp3', '', 1761754199, 1761754199),
(38523, 'Genesis 47:24', 'Genesis', 47, 24, 'خو کله چې د حاصل وخت راشي، نو تاسو به د هغې څخه پنځمه برخه فرعون ته ورکړئ او پاتې څلور برخې د ځمکو د تخم او خپل ځان، خپلو کورنیو او خپلو ماشومانو ته د خوراک دپاره وساتئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_24.mp3', '', 1761754199, 1761754199),
(38524, 'Genesis 47:25', 'Genesis', 47, 25, 'هغوی وویل: «باداره، تاسو زمونږ سره نېکي وکړه او زمونږ ژوند مو وژغوره. نو مونږ به د فرعون غلامان یو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_25.mp3', '', 1761754199, 1761754199),
(38525, 'Genesis 47:26', 'Genesis', 47, 26, 'نو یوسف د مصر په خاوره کې دا قانون وټاکه چې د محصولاتو پنځمه برخه به د فرعون وي. دغه قانون تر نن ورځې پورې په خپل قوت پاتې دی. یوازې د کاهنانو ځمکه د فرعون جایداد نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_26.mp3', '', 1761754199, 1761754199),
(38526, 'Genesis 47:27', 'Genesis', 47, 27, 'نو اسراییلیان په مصر کې د جوشن په سیمه کې اوسېدل. په هغه ځای کې دوی شتمني لاسته راوړله او د ډېرو اولادونو خاوندان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_27.mp3', '', 1761754199, 1761754199),
(38527, 'Genesis 47:28', 'Genesis', 47, 28, 'یعقوب په مصر کې اوولس کاله ژوند وکړ او په یوسلو اووه څلوېښت کلنۍ کې مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_28.mp3', '', 1761754199, 1761754199),
(38528, 'Genesis 47:29', 'Genesis', 47, 29, 'کله چې د یعقوب د مرګ وخت رانژدې شو، هغه خپل زوی یوسف راوغوښت او هغه ته یې وویل: «که چېرې زه درباندې په رښتیا ګران یم، نو خپل لاس دې زما د ورون لاندې کېږده او زما سره قسم وخوره چې ما به په مصر کې نه ښخوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_29.mp3', '', 1761754199, 1761754199),
(38529, 'Genesis 47:30', 'Genesis', 47, 30, 'زه غواړم په هغه ځای کې ښخ کړای شم چې زما نیکونه په کې ښخ دي. ما د مصر څخه یوسه او په کوم ځای کې چې هغوی ښخ شوي دي هلته مې ښخ کړه.» یوسف ځواب ورکړ: «څنګه چې ته وایې همداسې به وکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_30.mp3', '', 1761754199, 1761754199),
(38530, 'Genesis 47:31', 'Genesis', 47, 31, 'یعقوب وویل: «ماته قسم وخوره چې ته به دا کار کوې.» یوسف قسم وخوړ او یعقوب په خپل کټ باندې سر ټیټ کړ او شکر یې ادا کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_31.mp3', '', 1761754199, 1761754199),
(38531, 'Genesis 2:1', 'Genesis', 2, 1, 'نو ځمکه او اسمانونه او نور ټول شیان جوړ شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_1.mp3', '', 1761754199, 1761754199),
(38532, 'Genesis 2:2', 'Genesis', 2, 2, 'په اوومه ورځ خدای هغه ټول کارونه چې کول یې، سرته ورسول او کار یې بس کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_2.mp3', '', 1761754199, 1761754199),
(38533, 'Genesis 2:3', 'Genesis', 2, 3, 'خدای اوومه ورځ مبارکه وبلله او هغه یې ځانګړې وګرځوله، ځکه چې په هغه ورځ هغه پیدایښت پوره کړ او کار یې بس کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_3.mp3', '', 1761754199, 1761754199),
(38534, 'Genesis 2:4', 'Genesis', 2, 4, 'په دې ډول ځمکه او اسمانونه پیدا شول. د عدن باغ کله چې څښتن خدای اسمانونه او ځمکه جوړ کړل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_4.mp3', '', 1761754199, 1761754199),
(38535, 'Genesis 2:5', 'Genesis', 2, 5, 'تر هغه وخته پورې لا هېڅ واښه یا نور بوټي راشنه شوي نه وو، ځکه چې څښتن خدای باران نه ؤ اورولی او څوک نه ؤ چې په ځمکه باندې کار وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_5.mp3', '', 1761754199, 1761754199),
(38536, 'Genesis 2:6', 'Genesis', 2, 6, 'نو د ځمکې څخه د اوبو ویالې راووتلې او د ځمکې مخ ته یې اوبه ورکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_6.mp3', '', 1761754199, 1761754199),
(38537, 'Genesis 2:7', 'Genesis', 2, 7, 'څښتن خدای خاوره راواخیستله او د هغې څخه یې انسان جوړ کړ او د هغه په پوزه کې یې د ژوندون روح پو کړ او هغه ژوندی بدن شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_7.mp3', '', 1761754199, 1761754199),
(38538, 'Genesis 2:8', 'Genesis', 2, 8, 'څښتن خدای په عدن کې لمرخاته خواته یو باغ جوړ کړ او هغه انسان چې هغه جوړ کړی ؤ، هغه ته یې په دې باغ کې ځای ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_8.mp3', '', 1761754199, 1761754199),
(38539, 'Genesis 2:9', 'Genesis', 2, 9, 'څښتن خدای په دې باغ کې هر ډول ښایسته او مېوه لرونکې ونې راشنې کړلې او د باغ په منځ کې دوه نورې ونې وې. یوه د ژوندانه ونه او بله د ښو او بدو د پېژندلو ونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_9.mp3', '', 1761754199, 1761754199),
(38540, 'Genesis 2:10', 'Genesis', 2, 10, 'د عدن څخه یو سیند جاري شو چې باغ ته اوبه ورکړي او دا سیند بیا په څلورو سیندونو باندې ووېشل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_10.mp3', '', 1761754199, 1761754199),
(38541, 'Genesis 2:11', 'Genesis', 2, 11, 'د لومړني سیند نوم فیشون دی چې د حویله په ټول هېواد باندې راتاو شوی دی او هلته سره زر دي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_11.mp3', '', 1761754199, 1761754199),
(38542, 'Genesis 2:12', 'Genesis', 2, 12, 'چې د هغه ځای سره زر ډېر ښه دي. د خوشبویۍ مواد او د عقیقو تیږې هم په کې پیدا کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_12.mp3', '', 1761754199, 1761754199),
(38543, 'Genesis 2:13', 'Genesis', 2, 13, 'دوهم یې د جیحون سیند دی چې د کوش د ټولې ځمکې څخه راتاو شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_13.mp3', '', 1761754199, 1761754199),
(38544, 'Genesis 2:14', 'Genesis', 2, 14, 'درېم سیند د دجلې په نوم یادیږي چې د آشور لمرخاته خواته بهیږي او څلورم د فرات سیند دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_14.mp3', '', 1761754199, 1761754199),
(38545, 'Genesis 2:15', 'Genesis', 2, 15, 'نو څښتن خدای آدم ته د عدن په باغ کې ځای ورکړ چې د هغه خدمت او ساتنه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_15.mp3', '', 1761754199, 1761754199),
(38546, 'Genesis 2:16', 'Genesis', 2, 16, 'څښتن خدای آدم ته وویل: «د باغ د ټولو ونو څخه مېوه خوړلی شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_16.mp3', '', 1761754199, 1761754199),
(38547, 'Genesis 2:17', 'Genesis', 2, 17, 'خو د ښو او بدو د پېژندلو د ونې څخه نه، ځکه کله چې د هغې ونې مېوه وخورې بې له شکه چې مړ به شې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_17.mp3', '', 1761754199, 1761754199),
(38548, 'Genesis 2:18', 'Genesis', 2, 18, 'څښتن خدای وویل: «دا ښه نه دی چې آدم دې یوازې اوسي، زه به د هغه دپاره یوه مناسبه ملګرې جوړوم چې د هغه سره مرسته وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_18.mp3', '', 1761754199, 1761754199),
(38549, 'Genesis 2:19', 'Genesis', 2, 19, 'نو بیا څښتن خدای د خاورې څخه ټول حیوانات او مرغان جوړ کړل او هغه یې آدم ته راوستل، ترڅو وګوري چې په هغوی باندې کوم نوم ږدي. په دې ډول په هغوی ټولو باندې نومونه کېښودل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_19.mp3', '', 1761754199, 1761754199),
(38550, 'Genesis 2:20', 'Genesis', 2, 20, 'نو آدم په ټولو کورني او وحشي حیواناتو او مرغانو باندې نومونه کېښودل. د هغوی څخه یو هم د آدم دپاره مناسب ملګری نه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_20.mp3', '', 1761754199, 1761754199),
(38551, 'Genesis 2:21', 'Genesis', 2, 21, 'نو څښتن خدای آدم په درانه خوب باندې ویده کړ او د هغه د پوښتیو څخه یې یوه راواخیستله او د هغې ځای یې په غوښه باندې ډک کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_21.mp3', '', 1761754199, 1761754199),
(38552, 'Genesis 2:22', 'Genesis', 2, 22, 'څښتن خدای د هغې پوښتۍ څخه ښځه جوړه کړه او هغه یې آدم ته راوستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_22.mp3', '', 1761754199, 1761754199),
(38553, 'Genesis 2:23', 'Genesis', 2, 23, 'آدم وویل: دلته اوس شته یو څوک زما په شان اخیستل شوی یې هډوکی زما د هډوکو څخه او غوښه یې زما د غوښې څخه د هغې نوم دی ښځه ځکه اخیستل شوې هغه د سړي څخه ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_23.mp3', '', 1761754199, 1761754199),
(38554, 'Genesis 2:24', 'Genesis', 2, 24, 'له همدې امله سړی خپل مور او پلار پرېږدي او د خپلې ښځې سره یوځای کیږي او دواړه یو بدن شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_24.mp3', '', 1761754199, 1761754199),
(38555, 'Genesis 2:25', 'Genesis', 2, 25, 'سره د دې چې آدم او د هغه ښځه دواړه لوڅ وو، خو دوی نه شرمېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis2_verse_25.mp3', '', 1761754199, 1761754199),
(38556, 'Hosea 10:1', 'Hosea', 10, 1, 'د اسراییلو قوم د انګورو د یو داسې تاک په شان ؤ چې د انګورو نه ډک ؤ. هرڅومره چې د هغه مېوه زیاتېدله، نو هماغومره ډېر د بتانو د قربانۍ ځایونه به یې جوړول. هرڅومره چې د هغوی د ځمکې حاصلات زیاتېدل، نو هغوی د تیږو مذهبي ستنې ښایسته کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_1.mp3', '', 1761754199, 1761754199),
(38557, 'Hosea 10:2', 'Hosea', 10, 2, 'د هغو خلکو چې زړونه یې د چل او غولونې نه ډک دي، نو اوس به د خپلو ګناهونو له امله ځوریږي. خدای به د هغوی د قربانۍ ځایونه وران کړي او د هغوی د تیږو ستنې به له منځه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_2.mp3', '', 1761754199, 1761754199),
(38558, 'Hosea 10:3', 'Hosea', 10, 3, 'بیا به دا خلک ووایي: «مونږ پاچا نه لرو، ځکه چې مونږ د څښتن څخه ونه وېرېدلو. خو که مونږ پاچا درلودلی، نو هغه به زمونږ دپاره څه کولای شول؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_3.mp3', '', 1761754199, 1761754199),
(38559, 'Hosea 10:4', 'Hosea', 10, 4, 'د اسراییلو پاچاهان هسې خبرې کوي او د دروغو وعدې کوي او بې‌ګټې تړونونه کوي. انصاف په بې‌انصافۍ باندې بدل شوی دی لکه په قلبه شوي پټي کې چې زهرجن بوټي راشنه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_4.mp3', '', 1761754199, 1761754199),
(38560, 'Hosea 10:5', 'Hosea', 10, 5, 'کوم خلک چې په سامرې کې اوسیږي، هغوی به ووېریږي او په بیت‌آون کې د سرو زرو د خوسي د ورکېدلو په خاطر به ویر وکړي. خلک او د بت کاهنان به په دې خاطر چې د هغه شان او شوکت به له منځه لاړ شي، نو هغوی به ورباندې ژړا او انګولا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_5.mp3', '', 1761754199, 1761754199),
(38561, 'Hosea 10:6', 'Hosea', 10, 6, 'حتی هغه بت به هم آشور ته یووړل شي چې لوی امپراتور ته به د باج په توګه ورکړل شي. د اسراییلو خلک به په هغه بت باندې د تکیه کولو په سبب وشرمیږي او خجالته به شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_6.mp3', '', 1761754199, 1761754199),
(38562, 'Hosea 10:7', 'Hosea', 10, 7, 'د سامریې پاچا به داسې یووړل شي لکه د اوبو په سر باندې چې د لرګي یوه کوچنۍ ټوټه روانه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_7.mp3', '', 1761754199, 1761754199),
(38563, 'Hosea 10:8', 'Hosea', 10, 8, 'د آون هغه سیمه‌ییز عبادتځایونه به له منځه لاړ شي چې د اسراییلو خلکو په کې ګناه کوله. د هغوی په قربانګاوو باندې به اغزي او هرزه بوټي راشنه شي. خلک به غرونو ته چیغې وهي چې مونږ پټ کړئ! او غونډیو ته به چیغې وهي چې په مونږ باندې راولوېږئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_8.mp3', '', 1761754199, 1761754199),
(38564, 'Hosea 10:9', 'Hosea', 10, 9, 'څښتن وایي: «ای د اسراییلو خلکو، د هماغه وخت نه چې تاسو په جبعه کې ګناه کړې ده، تر‌اوسه پورې زما په وړاندې د ګناه کولو نه لاس نه اخلئ. ایا دا مناسبه نه وه چې د جبعې په بدکاره خلکو باندې حمله وشوه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_9.mp3', '', 1761754199, 1761754199),
(38565, 'Hosea 10:10', 'Hosea', 10, 10, 'کله چې زه وغواړم، هغوی ته به سزا ورکړم. نور قومونه به د هغوی په وړاندې سره یوځای شي او هغوی به د خپلو زیاتو ګناهونو له امله په زنځیرونو وتړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_10.mp3', '', 1761754199, 1761754199),
(38566, 'Hosea 10:11', 'Hosea', 10, 11, 'اسراییل په یو وخت کې د ښه روزل شوي خوسي په شان ؤ چې د غلو دانو غوبل کولو ته به خوشحاله ؤ. خو زه به د هغه په ښایسته غاړه باندې جغ ږدم او د سخت کار دپاره به یې تیاروم. ما یهودا دې ته مجبوره کړ چې یوې کش کړي او یعقوب مې مجبور کړ چې ماله کش کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_11.mp3', '', 1761754199, 1761754199),
(38567, 'Hosea 10:12', 'Hosea', 10, 12, 'نو د عدالت تخم وکرئ، ترڅو د تلپاتې مینې حاصل ورڅخه ورېبئ. د خپلو زړونو سخته ځمکه نرمه کړئ، ځکه چې اوس د دې وخت رارسېدلی دی چې د څښتن په لټه کې اوسئ، ترڅو زه راشم او د عدالت باران په تاسو باندې ووروم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_12.mp3', '', 1761754199, 1761754199),
(38568, 'Hosea 10:13', 'Hosea', 10, 13, 'خو تاسو د بدکارۍ تخم وکاره او د بې‌انصافۍ حاصل مو ورېبه. تاسو د خپلو دروغو د حاصل مېوه وخوړله. ځکه چې تاسو په خپل قوت او په خپلو ډېرو جنګیالیو باندې تکیه وکړه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_13.mp3', '', 1761754199, 1761754199),
(38569, 'Hosea 10:14', 'Hosea', 10, 14, 'نو ستاسو په خلکو باندې به د جنګ اوازونه راشي او ستاسو ټولې قوي کلاګانې به ورانې شي. دا به د هغې ورځې په شان وي لکه څنګه چې شلمان پاچا چې د بیت‌اربیل ښار په جنګ کې وران کړ او د هغوی میندې او ماشومان به په ځمکه راوغورځیږي او مړه به شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_14.mp3', '', 1761754199, 1761754199),
(38570, 'Hosea 10:15', 'Hosea', 10, 15, 'نو ای د بیت‌ییل خلکو، ستاسو سره به هم د هغو ډېرو بدو عملونو له امله چې کړي مو دي، همداسې کار کیږي. څنګه چې جنګ پیل شي، نو د اسراییلو پاچا به په بشپړه توګه تباه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea10_verse_15.mp3', '', 1761754199, 1761754199),
(38571, 'Esther 3:1', 'Esther', 3, 1, 'څه موده وروسته خشایار پاچا د همداتا زوی هامان ته چې د اجاج د طایفې ؤ، ترفیع ورکړه. هغه یې په خپلې امپراتورۍ کې لومړی وزیر کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_1.mp3', '', 1761754199, 1761754199),
(38572, 'Esther 3:2', 'Esther', 3, 2, 'پاچا امر وکړ چې ټول درباریان دې هامان ته د درناوي په خاطر خپل سرونه ټیټ کړي. هغوی ټولو همداسې وکړل، پرته له مردخای څخه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_2.mp3', '', 1761754199, 1761754199),
(38573, 'Esther 3:3', 'Esther', 3, 3, 'نو هغو نورو درباریانو چې د پاچا خدمت کاوه د مردخای څخه پوښتنه وکړه: «ته ولې د پاچا د حکم څخه سرغړونه کوې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_3.mp3', '', 1761754199, 1761754199),
(38574, 'Esther 3:4', 'Esther', 3, 4, 'هغوی به هره ورځ مردخای دې ته هڅاوه چې دا خبره ومني، خو هغه به هغوی ته غوږ نه نیوه. هغه به ویل: «زه یهودي یم او نه شم کولای چې هامان ته د درناوي سر ټیټ کړم.» نو هغوی هامان ته په دې هکله خبر ورکړ چې وګوري چې ایا هغه د مردخای چلند زغمي او که نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_4.mp3', '', 1761754199, 1761754199),
(38575, 'Esther 3:5', 'Esther', 3, 5, 'کله چې هامان پوه شو چې مردخای ده ته د درناوي په خاطر خپل سر نه ټیټوي، نو هغه سخت په قهر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_5.mp3', '', 1761754199, 1761754199),
(38576, 'Esther 3:6', 'Esther', 3, 6, 'کله چې هغه پوه شو چې مردخای یهودي دی، هغه دا پرېکړه وکړه چې یوازې د مردخای وژل بس نه دي. هغه دا پلان جوړ کړ چې هغه ټول یهودیان چې د خشایار پاچا په ټوله امپراتورۍ کې دي، ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_6.mp3', '', 1761754199, 1761754199),
(38577, 'Esther 3:7', 'Esther', 3, 7, 'د خشایار پاچا د امپراتورۍ د دولسم کال په لومړۍ میاشت چې د نیسان میاشت وه، هامان امر وکړ چې د ده په وړاندې پوریم یعنې پچه واچوي چې د دې دسیسې د سرته رسولو دپاره کومه ورځ او کومه میاشت ښه ده. نو د دولسمې میاشتې یعنې د اذر د میاشتې دیارلسمه ورځ وټاکل شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_7.mp3', '', 1761754199, 1761754199),
(38578, 'Esther 3:8', 'Esther', 3, 8, 'نو هامان خشایار پاچا ته وویل: «یو قوم دی چې ستاسو د امپراتورۍ د ټولو ولایتونو د قومونو په منځ کې خپور شوی دی چې دود یې د هغو ټولو قومونو نه فرق لري او د پاچا د قانون څخه اطاعت نه کوي، دا د پاچا په ګټه نه ده چې هغوی وزغمي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_8.mp3', '', 1761754199, 1761754199),
(38579, 'Esther 3:9', 'Esther', 3, 9, 'که ستاسو اعلیحضرت خوښه وي، یو فرمان جاري کړئ چې هغوی ووژل شي. که تاسو دا کار وکړئ، نو زه وعده کوم چې درې سوه څلوېښت ټنه سپین زر به د شاهي اداري چارو دپاره شاهي خزانې ته ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_9.mp3', '', 1761754199, 1761754199),
(38580, 'Esther 3:10', 'Esther', 3, 10, 'پاچا خپله د مهر ګوته چې په هغې باندې د پاچا فرمانونه مهر کېدل، د خپلې ګوتې راوویستله او هغه یې هامان د اجاجي همداتا زوی ته چې د یهودیانو دښمن ؤ، ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_10.mp3', '', 1761754199, 1761754199),
(38581, 'Esther 3:11', 'Esther', 3, 11, 'پاچا هغه ته وویل: «دا قوم او د هغوی پیسې دې ستا وي، نو څنګه چې ستا خوښه وي هماغسې ورسره وکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_11.mp3', '', 1761754199, 1761754199),
(38582, 'Esther 3:12', 'Esther', 3, 12, 'نو د لومړۍ میاشتې په دیارلسمه ورځ هامان د پاچا منشیان راوغوښتل. هغوی د هامان امرونه هر ولایت ته د هغوی په خط او د هر قوم په ژبه د پاچا له خوا ټاکل شویو والیانو، د بېلابېلو ولایتونو نورو والیانو او د مختلفو قومونو مامورینو ته ولیکل. هغه فرمانونه د خشایار پاچا په نامه ولیکل او مهر شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_12.mp3', '', 1761754199, 1761754199),
(38583, 'Esther 3:13', 'Esther', 3, 13, 'پیغامونه د دې امر سره د قاصدانو په وسیله د پاچا ټولو ولایتونو ته ولېږل شول چې ټول یهودیان، زوړ او ځوان، ښځې او ماشومان دې په یوه ورځ یعنې د دولسمې میاشتې په دیارلسمه نېټه چې د اذر میاشت وه، ووژل شي. هغوی دې په بې رحمۍ سره ووژل شي او د هغوی مالونه دې لوټ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_13.mp3', '', 1761754199, 1761754199),
(38584, 'Esther 3:14', 'Esther', 3, 14, 'د فرمان د متن یو نقل دې د قانون په توګه هر ولایت ته صادر شي او د هر قوم خلکو ته دې په ډاګه شي، ترڅو هغوی د هغې ورځې دپاره تیار اوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_14.mp3', '', 1761754199, 1761754199),
(38585, 'Esther 3:15', 'Esther', 3, 15, 'د پاچا په امر دا فرمان د شوش په بالاحصار کې خپور شو او قاصدانو دغه خبر په بیړه ولایتونو ته ورساوه. په داسې حال کې چې پاچا او هامان ناست وو او شراب یې څښل، خو د شوش په ښار کې وارخطایي او ګډوډي وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther3_verse_15.mp3', '', 1761754199, 1761754199),
(38586, 'Job 17:1', 'Job', 17, 1, 'زما زور ختم شوے دے او زما ورځې لنډې شوې دى، او قبر زما دپاره تيار دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_1.mp3', '', 1761754199, 1761754199),
(38587, 'Job 17:2', 'Job', 17, 2, 'زما نه ګېرچاپېره مسخرې کوونکى راتاو دى، او زۀ ګورم چې هغوئ ما ته سپکې خبرې کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_2.mp3', '', 1761754199, 1761754199),
(38588, 'Job 17:3', 'Job', 17, 3, 'اے خُدايه پاکه، تۀ زما ضمانت وکړه، ځکه چې بل هيڅ څوک به زما ذمه وارى وانۀ خلى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_3.mp3', '', 1761754199, 1761754199),
(38589, 'Job 17:4', 'Job', 17, 4, 'ځکه چې تا د هغوئ په ذهنونو باندې پړدې لګولې دى، هغوئ مۀ پرېږده چې په ما غالب شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_4.mp3', '', 1761754199, 1761754199),
(38590, 'Job 17:5', 'Job', 17, 5, 'څوک چې د خپلې فائدې دپاره دوستان دوکه کوى، نو د هغوئ د اولاد سترګې به ړندې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_5.mp3', '', 1761754199, 1761754199),
(38591, 'Job 17:6', 'Job', 17, 6, 'خُدائ پاک زۀ د خلقو دپاره د خندا کړے يم، هغوئ زما په مخ باندې توکاڼى توکى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_6.mp3', '', 1761754199, 1761754199),
(38592, 'Job 17:7', 'Job', 17, 7, 'د غم په وجه زما سترګې سرې شوې دى، او زما بدن اوچ کلک شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_7.mp3', '', 1761754199, 1761754199),
(38593, 'Job 17:8', 'Job', 17, 8, 'کله چې نېکان خلق ما وګورى نو په لړزان شى، او بې‌ګناه خلق د خُدائ پاک نه د منکرو خلقو مخالفت کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_8.mp3', '', 1761754199, 1761754199),
(38594, 'Job 17:9', 'Job', 17, 9, 'خو صادقان د خپلې لارې نه نۀ اوړى، چې صادقان ورځ په ورځ نور هم تکړه کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_9.mp3', '', 1761754199, 1761754199),
(38595, 'Job 17:10', 'Job', 17, 10, 'اوس تاسو ټول چرته ما ته څۀ سمه خبره وکړئ، خو بيا به هم په تاسو کښې يو هوښيار کس پېدا نۀ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_10.mp3', '', 1761754199, 1761754199),
(38596, 'Job 17:11', 'Job', 17, 11, 'زما دوران تېر شو او زما منصوبې ناکامه شوې، زما نه زما اُميدونه ختم شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_11.mp3', '', 1761754199, 1761754199),
(38597, 'Job 17:12', 'Job', 17, 12, 'هغوئ د شپې نه ورځ جوړوى، او رڼا ته تيارۀ وائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_12.mp3', '', 1761754199, 1761754199),
(38598, 'Job 17:13', 'Job', 17, 13, 'زۀ د مرګ په طمع يم، او زۀ به تل په تيارۀ کښې پروت يم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_13.mp3', '', 1761754199, 1761754199),
(38599, 'Job 17:14', 'Job', 17, 14, 'کۀ زۀ قبر ته ووايم چې تۀ زما پلار يې، او چينجو ته ووايم چې تاسو زما مور يا خور يئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_14.mp3', '', 1761754199, 1761754199),
(38600, 'Job 17:15', 'Job', 17, 15, 'نو بيا زما اُميد چرته دے؟ او دا چا ته ښکارى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_15.mp3', '', 1761754199, 1761754199),
(38601, 'Job 17:16', 'Job', 17, 16, 'نو زما ټول اُميدونه به په قبر کښې فنا شى؟ او زما ټول ارمانونه به خاورې شى څۀ؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job17_verse_16.mp3', '', 1761754199, 1761754199),
(38602, 'Job 20:1', 'Job', 20, 1, 'بيا ضوفر نعماتى ورته ووئيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_1.mp3', '', 1761754199, 1761754199),
(38603, 'Job 20:2', 'Job', 20, 2, '”زما زړۀ وائى چې جواب درکړم، ځکه چې ستا خبرو زۀ خفه کړے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_2.mp3', '', 1761754199, 1761754199),
(38604, 'Job 20:3', 'Job', 20, 3, 'تا چې څۀ وفرمائيل هغه زما بې‌عزتى ده، او زما زړۀ ما ته وائى چې جواب درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_3.mp3', '', 1761754199, 1761754199),
(38605, 'Job 20:4', 'Job', 20, 4, 'تا ته د ډېر وخت نه د دې پته ده، د هغه وخت نه چې کله بنى آدم په زمکه پېدا شوے وو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_4.mp3', '', 1761754199, 1761754199),
(38606, 'Job 20:5', 'Job', 20, 5, 'د بدعمله کس کاميابى لنډه وى، او د خُدائ پاک نه منکرو خلقو خوشحالى د لږ وخت دپاره وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_5.mp3', '', 1761754199, 1761754199),
(38607, 'Job 20:6', 'Job', 20, 6, 'کۀ هغوئ د آسمانونو پورې هم اوچت شوى وى، او د هغوئ سرونه وريځو ته رسېدلى وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_6.mp3', '', 1761754199, 1761754199),
(38608, 'Job 20:7', 'Job', 20, 7, 'هغوئ به د خپلو متيازو په شان د تل دپاره ختم شى، چا چې هغوئ ليدلى وى نو هغوئ به ووائى چې څۀ شول؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_7.mp3', '', 1761754199, 1761754199),
(38609, 'Job 20:8', 'Job', 20, 8, 'هغوئ به د يو خوب په شان تېر شى او ورک به شى، هغوئ به د شپې د خوب په شان فنا شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_8.mp3', '', 1761754199, 1761754199),
(38610, 'Job 20:9', 'Job', 20, 9, 'کومو خلقو چې هغوئ ليدلى وى نو هغه به يې نور ونۀ ګورى، او چې چرته اوسېدل نو د هغه ځائ خلق به يې ياد نۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_9.mp3', '', 1761754199, 1761754199);